import React, { useState, useEffect } from 'react';
import { Container, Row, Col, Form, FormGroup, Button, Input, Label } from 'reactstrap';
import { useParams, useNavigate } from 'react-router-dom';
import { BASE_URL } from '../../utils/config';

const CreateTour = () => {
   const { id } = useParams();
   const isUpdateMode = !!id;
   const navigate = useNavigate();

   // State lưu trữ thông tin chữ
   const [formData, setFormData] = useState({
      title: '',
      city: '',
      address: '',
      distance: 0,
      price: 0,
      maxGroupSize: 0,
      desc: '',
      featured: false
   });

   // State lưu trữ file ảnh
   const [mainPhoto, setMainPhoto] = useState(null);
   const [galleryPhotos, setGalleryPhotos] = useState([]);

   // 1. Lấy dữ liệu cũ nếu là chế độ Update
   useEffect(() => {
      if (isUpdateMode) {
         const fetchTour = async () => {
            try {
               const res = await fetch(`${BASE_URL}/tours/${id}`);
               const result = await res.json();
               if (res.ok) setFormData(result.data);
            } catch (err) {
               console.log("Lỗi tải dữ liệu tour");
            }
         };
         fetchTour();
      }
   }, [id, isUpdateMode]);

   // 2. Xử lý thay đổi input chữ
   const handleChange = e => {
      const { id, value, type, checked } = e.target;
      setFormData(prev => ({ 
         ...prev, 
         [id]: type === 'checkbox' ? checked : value 
      }));
   };

   // 3. Gửi dữ liệu (POST hoặc PUT)
   const handleSubmit = async e => {
      e.preventDefault();
      const token = localStorage.getItem('token');
      const data = new FormData();

      // Đẩy các trường text vào FormData
      Object.keys(formData).forEach(key => {
         if(key !== 'reviews' && key !== 'photo' && key !== 'images') {
            data.append(key, formData[key]);
         }
      });

      // Đẩy file ảnh vào FormData
      if (mainPhoto) data.append('photo', mainPhoto);
      galleryPhotos.forEach(file => {
         data.append('images', file);
      });

      try {
         const url = isUpdateMode ? `${BASE_URL}/tours/${id}` : `${BASE_URL}/tours`;
         const method = isUpdateMode ? 'PUT' : 'POST';

         const res = await fetch(url, {
            method,
            headers: { 'Authorization': `Bearer ${token}` },
            body: data
         });

         const result = await res.json();
         if (res.ok) {
            alert(isUpdateMode ? "Cập nhật thành công!" : "Thêm tour thành công!");
            navigate('/admin/tours'); // Quay lại trang danh sách
         } else {
            alert(result.message);
         }
      } catch (err) {
         alert("Lỗi kết nối server!");
      }
   };

   return (
      <section className="mt-5 mb-5">
         <Container>
            <Row>
               <Col lg='10' className="m-auto">
                  <div className="create__tour-content shadow-lg p-5 rounded-4 bg-white">
                     <h2 className="mb-5 text-center fw-bold text-primary">
                        {isUpdateMode ? "CHỈNH SỬA THÔNG TIN TOUR" : "THÊM TOUR DU LỊCH MỚI"}
                     </h2>
                     
                     <Form onSubmit={handleSubmit}>
                        {/* HÀNG 1: Tên và Thành phố */}
                        <Row>
                           <Col md='8'>
                              <FormGroup>
                                 <Label className="fw-bold">Tên Tour</Label>
                                 <Input type="text" id="title" value={formData.title} onChange={handleChange} placeholder="Ví dụ: Vịnh Hạ Long Luxury" required />
                              </FormGroup>
                           </Col>
                           <Col md='4'>
                              <FormGroup>
                                 <Label className="fw-bold">Thành phố</Label>
                                 <Input type="text" id="city" value={formData.city} onChange={handleChange} placeholder="Quảng Ninh" required />
                              </FormGroup>
                           </Col>
                        </Row>

                        {/* HÀNG 2: Địa chỉ cụ thể */}
                        <FormGroup>
                           <Label className="fw-bold">Địa chỉ chi tiết</Label>
                           <Input type="text" id="address" value={formData.address} onChange={handleChange} placeholder="Số 123, Cảng Tuần Châu..." required />
                        </FormGroup>

                        {/* HÀNG 3: Giá, Khoảng cách, Số người */}
                        <Row>
                           <Col md='4'>
                              <FormGroup>
                                 <Label className="fw-bold">Giá tour (vnđ)</Label>
                                 <Input type="number" id="price" value={formData.price} onChange={handleChange} required />
                              </FormGroup>
                           </Col>
                           <Col md='4'>
                              <FormGroup>
                                 <Label className="fw-bold">Khoảng cách (km)</Label>
                                 <Input type="number" id="distance" value={formData.distance} onChange={handleChange} required />
                              </FormGroup>
                           </Col>
                           <Col md='4'>
                              <FormGroup>
                                 <Label className="fw-bold">Số khách tối đa</Label>
                                 <Input type="number" id="maxGroupSize" value={formData.maxGroupSize} onChange={handleChange} required />
                              </FormGroup>
                           </Col>
                        </Row>

                        {/* HÀNG 4: Mô tả */}
                        <FormGroup>
                           <Label className="fw-bold">Mô tả Tour</Label>
                           <Input type="textarea" id="desc" value={formData.desc} onChange={handleChange} rows="5" placeholder="Viết giới thiệu về tour..." required />
                        </FormGroup>

                        {/* HÀNG 5: Upload Ảnh */}
                        <Row className="mb-4">
                           <Col md='6'>
                              <FormGroup className="p-3 border rounded shadow-sm">
                                 <Label className="fw-bold text-success">Ảnh đại diện (1 ảnh)</Label>
                                 <Input type="file" accept="image/*" onChange={e => setMainPhoto(e.target.files[0])} />
                                 {isUpdateMode && !mainPhoto && (
                                    <small className="text-muted">Đang dùng ảnh cũ từ server</small>
                                 )}
                              </FormGroup>
                           </Col>
                           <Col md='6'>
                              <FormGroup className="p-3 border rounded shadow-sm">
                                 <Label className="fw-bold text-info">Thư viện ảnh (Nhiều ảnh)</Label>
                                 <Input type="file" accept="image/*" multiple onChange={e => setGalleryPhotos(Array.from(e.target.files))} />
                              </FormGroup>
                           </Col>
                        </Row>

                        {/* HÀNG 6: Tùy chọn nổi bật */}
                        <FormGroup check className="mb-5">
                           <Label check className="fw-bold">
                              <Input type="checkbox" id="featured" checked={formData.featured} onChange={handleChange} />
                              {' '} Đánh dấu là Tour nổi bật (Hiện lên trang chủ)
                           </Label>
                        </FormGroup>

                        {/* NÚT BẤM GỬI */}
                        <div className="d-flex justify-content-center gap-3">
                           <Button type="button" color="secondary" onClick={() => navigate('/admin/tours')}>Hủy bỏ</Button>
                           <Button type="submit" color="primary" className="px-5">
                              {isUpdateMode ? "Cập nhật Tour" : "Xác nhận Thêm Tour"}
                           </Button>
                        </div>
                     </Form>
                  </div>
               </Col>
            </Row>
         </Container>
      </section>
   );
};

export default CreateTour;
